    vector<int> corpFlightBookings(vector<vector<int>>& bookings, int n) {
        vector<int> diff(n + 1, 0);
        for (auto& b : bookings) {
            diff[b[0] - 1] += b[2];
            diff[b[1]] -= b[2];
        }
        vector<int> ans(n);
        int cur = 0;
        for (int i = 0; i < n; ++i) {
            cur += diff[i];
            ans[i] = cur;
        }
        return ans;
    }
};

